def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find the repeated vertical color key: adjacent columns with uniform,
    # nonzero colors across three identical rows.
    key = None
    for r in range(h - 2):
        c = 0
        while c < w:
            if grid[r][c] and grid[r][c] == grid[r + 1][c] == grid[r + 2][c]:
                a = c
                vals = []
                while c < w and grid[r][c] and grid[r][c] == grid[r + 1][c] == grid[r + 2][c]:
                    vals.append(grid[r][c])
                    c += 1
                if len(vals) >= 3:
                    key = (r, a, vals)
                    break
            else:
                c += 1
        if key:
            break
    if key is None:
        return [row[:] for row in grid]
    kr, kc, colors = key
    excluded = {(rr, cc) for rr in range(kr, kr + 3) for cc in range(kc, kc + len(colors))}
    # Gather connected components outside the key.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or (r, c) in excluded or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if (0 <= nr < h and 0 <= nc < w and (nr,nc) not in excluded
                            and (nr,nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            comps.append((color, comp))
    # Use a component belonging to the ordered key colors as the shape template.
    candidates = [(color, comp) for color, comp in comps if color in colors]
    if not candidates:
        return [row[:] for row in grid]
    color, comp = max(candidates, key=lambda item: len(item[1]))
    shape_color_idx = colors.index(color)
    minr = min(r for r, c in comp)
    minc = min(c for r, c in comp)
    shape = {(r - minr, c - minc) for r, c in comp}
    sh = max(r for r, c in shape) + 1
    out = [[0] * w for _ in range(h)]
    top = minr - shape_color_idx * sh
    for i, new_color in enumerate(colors):
        for dr, dc in shape:
            rr, cc = top + i * sh + dr, minc + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = new_color
    return out

